from fractions import Fraction
def solve(t):
    count = 0
    for a in range(1, 7):
        for b in range(1, 7):
            for c in range(1, 7):
                if a + b + c == t:
                    count = count + 1
    print(f"sum {t}")
    print(f"  count: {count} of 216")
    print(f"  P = {count}/216 = {Fraction(count, 216)}")
k = int(input())
for i in range(k):
    solve(int(input()))
